      ],
      "reference_evidence": "The man is jumping in a way that wouldn't happen in real life and defies the law of physics as some sort of slow motion filter was put on this video",
      "candidate_evidence": "The person's hands and fingers morph, blur, and distort irregularly while flapping and moving during flight.",
      "basis": "explicit_separation",
      "reason_ko": "참조는 남자의 전신 점프 동작이 물리 법칙을 거스르고 슬로 모션처럼 어색하게 이루어지는 비물리적 운동 이상을 지적하는 반면, 후보는 비행 중 손과 손가락 부위의 기괴한 형태 변형 및 왜곡(morph, blur, distort) 현상을 지적하고 있어 문제시되는 상호작용 및 현상이 명백히 다릅니다.",
      "separation_basis": "different_interaction"
    }
  ]
}

